('lib/content/gpx_scolarite/dps_dpg/cadres_juridiques_pages/flagrant_delit/flagrant_delit_procedure_page.dart','f00481','3.3.11.1 — Les réquisitions à personnes qualifiées (art. 60 C.P.P.)',481,'_SubTitle','3.3.11.1 — Les réquisitions à personnes qualifiées (art. 60 C.P.P.)','3.3.11.1 — Les réquisitions à personnes qualifiées (art. 60 C.P.P.)','{}'::jsonb,true),
('lib/content/gpx_scolarite/dps_dpg/cadres_juridiques_pages/flagrant_delit/flagrant_delit_procedure_page.dart','f00482','3.3.11.1 — Les réquisitions à personnes qualifiées (art. 60 C.P.P.)',482,'_Paragraph','Les personnes qualifiées (médecins, experts, services de police technique et scientifique, etc.) peuvent être requises pour procéder à des examens, constatations ou analyses. ','Les personnes qualifiées (médecins, experts, services de police technique et scientifique, etc.) peuvent être requises pour procéder à des examens, constatations ou analyses. ','{}'::jsonb,true),
